func _nearest_walkable_cell(cell: Vector2i) -> Vector2i:
	if _is_walkable_cell(cell):
		return cell
	for radius in range(1, 5):
		for y in range(cell.y - radius, cell.y + radius + 1):
			for x in range(cell.x - radius, cell.x + radius + 1):
