					return candidate
	return cell


func _next_path_cell(start: Vector2i, goal: Vector2i) -> Vector2i:
	var directions := [Vector2i.RIGHT, Vector2i.LEFT, Vector2i.DOWN, Vector2i.UP]
	var queue: Array[Vector2i] = [start]
	var queue_index := 0
	var visited := {}
	var came_from := {}
	visited[start] = true

	while queue_index < queue.size():
		var current := queue[queue_index]
		queue_index += 1
		if current == goal:
			break
		for direction in directions:
			var next: Vector2i = current + direction
			if visited.has(next) or not _is_walkable_cell(next):
				continue
			visited[next] = true
			came_from[next] = current
			queue.append(next)

	if not visited.has(goal):
		return start

	var step := goal
	while came_from.has(step) and came_from[step] != start:
		step = came_from[step]
	return step


func _is_walkable_cell(cell: Vector2i) -> bool:
	if cell.y < 0 or cell.y >= world_grid.size():
		return false
	var row: Array = world_grid[cell.y]
	if cell.x < 0 or cell.x >= row.size():
		return false
	return int(row[cell.x]) == FLOOR


